const src = $json || {};
const body = src.body || {};
const headers = src.headers || {};

const cfg = {
  apiBaseUrl: String(src.apiBaseUrl || 'https://app2.simpletexting.com/v1').replace(/\/$/, ''),
  apiToken: String(src.apiToken || '').trim(),
  defaultDryRun: !!src.defaultDryRun,
  authHeaderName: String(src.authHeaderName || 'x-lt-webhook-key').toLowerCase(),
  authHeaderValue: String(src.authHeaderValue || ''),
  senderLabel: String(src.senderLabel || 'SimpleTexting').trim(),
  templateRegistryJson: String(src.templateRegistryJson || '{}').trim(),
};

const incomingAuth = headers[cfg.authHeaderName] || headers[cfg.authHeaderName.toLowerCase()] || '';
if (cfg.authHeaderValue && incomingAuth !== cfg.authHeaderValue) {
  return [{ json: { ok: false, error: 'unauthorized', message: 'Invalid webhook auth header' } }];
}

function clean(v) {
  return String(v || '').trim();
}

function parseBoolean(v, fallback) {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true', '1', 'yes', 'y'].includes(s)) return true;
  if (['false', '0', 'no', 'n'].includes(s)) return false;
  return fallback;
}

function normalizePhone(v) {
  const digits = clean(v).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1);
  return digits;
}

function normalizeTemplateKey(value) {
  return clean(value).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function buildVariableMap(payload) {
  const variables = (payload.variables && typeof payload.variables === 'object' && !Array.isArray(payload.variables)) ? payload.variables : {};
  const contact = (payload.contact && typeof payload.contact === 'object' && !Array.isArray(payload.contact)) ? payload.contact : {};
  const merged = { ...contact, ...payload, ...variables };
  delete merged.variables;
  delete merged.contact;
  return Object.fromEntries(Object.entries(merged).map(([key, value]) => [String(key), value == null ? '' : String(value)]));
}

function applyVariables(template, variableMap) {
  return String(template || '').replace(/{{\s*([^{}]+?)\s*}}/g, (_, key) => {
    const trimmed = String(key || '').trim();
    if (Object.prototype.hasOwnProperty.call(variableMap, trimmed)) return variableMap[trimmed];
    const normalized = trimmed.replace(/\./g, '_');
    if (Object.prototype.hasOwnProperty.call(variableMap, normalized)) return variableMap[normalized];
    return '';
  });
}

let templateRegistry = {};
try {
  templateRegistry = JSON.parse(cfg.templateRegistryJson || '{}');
} catch {
  return [{ json: { ok: false, error: 'invalid_template_registry', message: 'templateRegistryJson is not valid JSON' } }];
}

const templateAliases = {};
for (const [key, value] of Object.entries(templateRegistry)) {
  templateAliases[normalizeTemplateKey(key)] = key;
  const name = clean(value && typeof value === 'object' ? value.name : '');
  if (name) templateAliases[normalizeTemplateKey(name)] = key;
}

const dryRun = parseBoolean(body.dryRun, cfg.defaultDryRun);
const to = normalizePhone(body.to || body.phone || body.mobile || body.destination);
const rawMessage = clean(body.message || body.text || body.smsBody);
const templateKeyInput = clean(body.templateKey || body.snippetKey || body.template || body.smsTemplateKey);
const resolvedTemplateKey = templateKeyInput ? (templateAliases[normalizeTemplateKey(templateKeyInput)] || '') : '';
const templateEntry = resolvedTemplateKey ? templateRegistry[resolvedTemplateKey] : null;
const variableMap = buildVariableMap(body);
const templateMessage = templateEntry ? applyVariables(templateEntry.message || '', variableMap).trim() : '';
const message = rawMessage || templateMessage;
const contactId = clean(body.contactId);
const campaignKey = clean(body.campaignKey || body.sequenceKey || body.workflowKey);
const externalId = clean(body.externalId || body.messageKey || body.eventId);
const senderLabel = clean(body.senderLabel || cfg.senderLabel);
const templateName = clean(templateEntry && templateEntry.name ? templateEntry.name : '');

let mediaUrls = [];
if (Array.isArray(body.mediaUrls)) {
  mediaUrls = body.mediaUrls.map((v) => clean(v)).filter(Boolean);
} else if (body.mediaUrl) {
  mediaUrls = [clean(body.mediaUrl)].filter(Boolean);
}

if (!to) {
  return [{ json: { ok: false, error: 'missing_phone', message: 'Provide to/phone/mobile/destination' } }];
}
if (to.length !== 10) {
  return [{ json: { ok: false, error: 'invalid_phone', message: 'SimpleTexting SMS endpoint expects a 10-digit phone number', to } }];
}
if (!message) {
  return [{ json: { ok: false, error: 'missing_message', message: 'Provide message/text/smsBody or a valid templateKey' } }];
}
if (templateKeyInput && !templateEntry && !rawMessage) {
  return [{ json: { ok: false, error: 'unknown_template_key', message: 'Unknown templateKey', templateKey: templateKeyInput, availableTemplateKeys: Object.keys(templateRegistry) } }];
}

const isMms = mediaUrls.length > 0;
if (!isMms && message.length > 160) {
  return [{ json: { ok: false, error: 'sms_too_long', message: 'SMS message exceeds 160 characters; shorten it or send as MMS', length: message.length } }];
}
if (isMms && message.length > 1600) {
  return [{ json: { ok: false, error: 'mms_too_long', message: 'MMS message exceeds 1600 characters', length: message.length } }];
}
if (isMms && mediaUrls.length > 2) {
  return [{ json: { ok: false, error: 'too_many_media_urls', message: 'SimpleTexting allows at most 2 media URLs for MMS', count: mediaUrls.length } }];
}

if (dryRun) {
  return [{
    json: {
      ok: true,
      dryRun: true,
      action: isMms ? 'would_send_mms' : 'would_send_sms',
      provider: 'SimpleTexting',
      endpoint: isMms ? 'sendmms' : 'send',
      to,
      message,
      messageLength: message.length,
      mediaUrls,
      contactId,
      campaignKey,
      externalId,
      senderLabel,
      templateKey: resolvedTemplateKey || templateKeyInput || '',
      templateName,
    },
  }];
}

if (!cfg.apiToken) {
  return [{ json: { ok: false, error: 'missing_api_token', message: 'Missing SIMPLETEXTING_API_TOKEN in workflow config/env' } }];
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

const form = new URLSearchParams();
form.append('phone', to);
form.append('message', message);
if (isMms) {
  for (const mediaUrl of mediaUrls) form.append('mediaUrl', mediaUrl);
}

const endpoint = isMms ? 'sendmms' : 'send';
const options = {
  method: 'POST',
  url: `${cfg.apiBaseUrl}/${endpoint}`,
  headers: {
    Authorization: `Bearer ${cfg.apiToken}`,
    Accept: 'application/json',
    'Content-Type': 'application/x-www-form-urlencoded',
  },
  body: form.toString(),
  json: true,
};

try {
  const data = await doHttpRequest.call(this, options);
  return [{
    json: {
      ok: true,
      dryRun: false,
      action: isMms ? 'mms_sent' : 'sms_sent',
      provider: 'SimpleTexting',
      endpoint,
      to,
      contactId,
      campaignKey,
      externalId,
      senderLabel,
      templateKey: resolvedTemplateKey || templateKeyInput || '',
      templateName,
      messageLength: message.length,
      mediaUrls,
      providerResponse: data,
      providerMessageId: data?.smsid || data?.id || '',
    },
  }];
} catch (err) {
  return [{
    json: {
      ok: false,
      dryRun: false,
      error: 'simpletexting_send_failed',
      endpoint,
      to,
      contactId,
      campaignKey,
      externalId,
      senderLabel,
      templateKey: resolvedTemplateKey || templateKeyInput || '',
      templateName,
      details: err?.response?.body || err?.message || err,
      statusCode: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
    },
  }];
}
